const course: DeepCourse = {"slug":"pricing-and-negotiation","title":"Pricing &amp; Negotiation.","premium":false,"previewCount":3,"chunks":[{"kind":"html","value":"<section class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Money · free</p><h1 class=\"display-lg mt-4\">Pricing &amp; Negotiation<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Work out a number you can defend, say it without flinching, and raise it later without losing the client.</p><div class=\"mt-8\"><div class=\"flex flex-wrap items-center gap-2.5\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free course</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">9 modules</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">3h 58m of reading and doing</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">8 portfolio pieces</span></div><p class=\"mt-4 mb-2 text-[0.8125rem] text-muted\">Course content is based on active job listings and industry hiring patterns. These are practical guides, not formal certifications.</p></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><section class=\"px-5 pt-10 md:px-8\"><div class=\"mx-auto max-w-5xl\"><div id=\"plain-words\" class=\"rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><p class=\"eyebrow\">In plain words</p><p class=\"mt-3 max-w-3xl text-[1.0625rem] leading-[1.75] text-ink\">Money talk is the part nobody teaches. This course helps you work out what to charge — based on your real bills, not vibes — say it confidently, and handle a client who says ‘that’s too expensive’.</p><div class=\"mt-6 grid gap-5 sm:grid-cols-2\"><div><p class=\"eyebrow text-muted\">This is for you if</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">You’re charging whatever the client offers, or you haven’t raised your rate since you started.</p></div><div><p class=\"eyebrow text-muted\">You walk away with</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Your personal minimum rate, word-for-word scripts for the awkward conversations, and a plan for your next raise.</p></div></div></div></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"the-job\" class=\"scroll-mt-32\"><div class=\"space-y-5\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">Almost nobody in this market is underpaid because they lack skill. They are underpaid because they never named a number, never wrote down a scope, and never asked again after the first year. Those are three fixable habits, not a personality defect.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">This track treats pricing as arithmetic plus one uncomfortable sentence. The arithmetic is your floor, your fees, your unbilled hours, and your real effective rate. The uncomfortable sentence is the one where you say the number and then stop talking. We drill both.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">The running scenario is a VA at $6 an hour, 20 hours a week, supporting Bexley Wellness Co, a small US studio chain. Over nine modules you will build the floor, choose the model, quote, defend, handle scope creep, ask for $9, and know precisely when the correct answer is to leave.</p></div><dl class=\"mt-10 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">What this fixes</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Quoting blind, discounting on instinct, and staying at the starting rate for three years</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Core skill</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Say the number, then stop talking</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">The math</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Effective rate, not quoted rate. It is usually 20 to 40 percent lower</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Churn risk of a well-run raise</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Low. Reducing scope beats discounting in almost every case</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">What you end with</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">A floor, a rate card, three scripts, and a change request template</dd></div></dl></section><section class=\"mt-16\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What a shift actually looks like</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Monthly, 20 minutes</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Close the books</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Money received, fees paid, hours worked including unbilled. One number out: effective rate.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Per new enquiry</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Scope before price</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">You cannot quote a role. You can quote a list of outputs on a schedule.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">On the call</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Say the number</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Package, rate, invoicing cadence. Then silence, however long it lasts.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Whenever work appears</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Change request, same day</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">One paragraph: this is new, here is the time or cost, please approve. Sent before you start.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Every six months</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">The rate review</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Evidence pack, new rate, effective date 30 to 45 days out. Scheduled, not summoned by resentment.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Quarterly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Concentration check</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">No client should be more than half your income. If one is, that is a pricing risk, not just a sales one.</p></div></li></ol></section></div><section id=\"tools\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">The tools, and why each one exists</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Do not buy anything yet. Learn the free ones properly and use the client's licence for the rest — that is what everyone else is doing too.</p><div class=\"mt-8 space-y-8\"><div><p class=\"eyebrow text-muted\">Working out the number</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Sheets</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Your floor calculator, rate card, and monthly close. Nothing fancier is needed for years.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Toggl Track</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Independent time log. Turns \"it takes longer than you think\" into evidence.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Wise or Payoneer fee calculators</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Your rate is net of fees whether you calculated them or not.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">OnlineJobs.ph salary guide</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The one Philippine benchmark worth quoting in a negotiation.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Getting it agreed and paid</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">A one-page rate card</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Packages with inclusions. Stops every conversation restarting from zero.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">A written contract or scope email</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Even a numbered email both parties reply \"agreed\" to. Beats nothing by an enormous margin.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Change request template</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Three sentences, reused forever. The single highest-return document in this track.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Invoice template with terms</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Number, period, line items, due date, and what happens when it is late.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Loom</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Delivering a rate increase as a 90-second video reads warmer than an email and cannot be skimmed angrily.</p></li></ul></div></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://wise.com/ph/pricing/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Wise fees (PHP)</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Know exactly what a transfer costs before you quote a rate.</p></a></li><li class=\"h-full\"><a href=\"https://www.payoneer.com/about/fees/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Payoneer fee schedule</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The other common way clients pay. Compare before you pick.</p></a></li><li class=\"h-full\"><a href=\"https://www.xe.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">XE currency converter</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Check the mid-market rate so you know what a platform is really taking.</p></a></li><li class=\"h-full\"><a href=\"https://www.bir.gov.ph/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Bureau of Internal Revenue</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Registering as self-employed is cheaper than the fixer prices suggest. Official source.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section class=\"border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><section id=\"rates\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What this actually pays</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">General VA benchmarks from the OnlineJobs.ph April 2026 salary guide, used here as the sanity check on your own floor calculation rather than as a target. Specialist tracks such as SEO, ecommerce and real estate sit above these. The number you should ask for is your floor plus the evidence you can show, checked against this band.</p><div class=\"mt-7 rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><div class=\"space-y-7\"><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Beginner</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">3–5<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:25%;width:16.666666666666664%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Supervised, narrow, someone checks the output. A starting point with an expiry date.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 480–800/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Intermediate</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">6–9<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:50%;width:25%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">You own a workflow. Nobody checks it. You can name a metric you moved.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 960–1,440/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Expert</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">10–12<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:83.33333333333334%;width:16.666666666666664%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">You make decisions alone and carry risk. Price the responsibility, not the hours.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,600–1,920/mo full-time</p></div></div></div><p class=\"mt-7 border-t border-line pt-4 text-[0.75rem] leading-relaxed text-muted-2\">Directional market benchmarks, not a guarantee and not a ceiling. Source: <a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">OnlineJobs.ph salary guide, April 2026</a>. Monthly figures assume 40 hours a week, which most VA roles are not.</p></div><div class=\"mt-5 rounded-2xl border border-[#f4d9c6] bg-clay-wash/70 p-6 sm:p-7\"><p class=\"eyebrow text-clay-deep\">What actually moves you up a band</p><ul class=\"mt-3.5 grid gap-2.5 sm:grid-cols-2\"><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You can show a before and after number, measured over weeks</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You made a decision without asking and it was right</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You wrote the SOPs the team now trains on</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You cover hours that cost you your evenings</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You carry risk: money, client-facing communication, or confidential material</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You have another client, so no is a real option</li></ul></div></section></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><figure class=\"rounded-2xl border border-line bg-card p-7 shadow-card sm:p-9\"><figcaption class=\"flex flex-wrap items-center gap-3\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">Worker story</span><span class=\"text-[0.8125rem] text-muted\">One person's experience, not a universal rule</span></figcaption><h2 class=\"mt-4 font-display text-[1.5rem] font-semibold leading-snug text-ink\">\"My boss keeps saying my 3 hours of work is only worth 1 hour\"</h2><blockquote class=\"mt-5 border-l-2 border-clay pl-5 font-display text-[1.1875rem] italic leading-relaxed text-ink\">“No matter what receipts you provide, the bottomline is she does not want to pay you for the work you've done.”</blockquote><p class=\"mt-5 text-[0.9375rem] leading-relaxed text-ink-2\">In August 2026 a Filipino freelancer posted screenshots to r/buhaydigital. Their client had decided that work taking three hours should be billed as one. The freelancer had done everything right: sent links and screenshots for every task, with timestamps, and explained that they were not padding the work, just producing something polished. The client would not accept it. The top reply, with 84 upvotes, cut through the whole thread: no volume of receipts changes a client who has decided not to pay, so start looking for another client. A second commenter offered the only structural repair worth trying first: if you want to keep the money, switch to output-based pricing, for example $10 per post.</p><div class=\"mt-5 rounded-xl border border-teal-pale bg-teal-wash/60 p-4\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The lesson</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">There is a point where better evidence stops being the answer. If timestamps, links, and screenshots do not move someone, the disagreement was never about measurement, and every extra hour spent proving yourself is an hour donated. Try changing the pricing model once. If that is refused too, you have your answer, and the only real protection is having somewhere else to go.</p></div><a href=\"https://old.reddit.com/r/buhaydigital/comments/1vez4si/my_boss_keeps_saying_my_3_hours_of_work_is_only/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"mt-4 inline-block text-[0.8125rem] font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">Read the original thread — r/buhaydigital, August 2026</a></figure></div><section id=\"first-client\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Getting the first one to say yes</h2><ol class=\"mt-7 space-y-4\"><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">01</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Calculate the floor before you talk to anyone</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Not a feeling about what is fair. A sheet with your costs, tax, fees and realistic billable hours in it. Everything downstream is easier once this number exists.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">02</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Put a number in every profile field that asks for one</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">\"Negotiable\" tells clients nothing and attracts the ones who wanted to choose. A stated rate is a filter working for you while you sleep.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">03</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Quote a package, never a bare hourly</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">\"$9 an hour\" invites comparison shopping. \"20 hours a week covering these five outputs, $720 a fortnight\" invites a decision about the work.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">04</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Get the scope in writing on day zero</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A numbered email both of you reply \"agreed\" to is enough. Every scope conversation you avoid now becomes an argument you lose later.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">05</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Diarise the first review before you start</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Six months out, in your calendar, on the day you sign. Reviews that are scheduled happen. Reviews that wait for the right moment never do.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">06</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Never let one client exceed half your income</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">This is a pricing rule disguised as a sales rule. You cannot hold a number with someone who could end your month.</p></div></li></ol><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">What goes in the portfolio</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">Every one of these comes out of the exercises above. Finish the track and you have the folder, not just the knowledge.</p><ul class=\"mt-5 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A one-page rate card with three packages</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Turns pricing from an interrogation into a menu, and the middle option usually wins.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A scope document from a real or fictional engagement</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Shows a client you will not be one of the people who never defines the job.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A change request you actually sent</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">The single clearest signal that you manage scope like a business, not like an employee.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">An absorbed-work log</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Your evidence pack at review time, and a reality check on your own generosity.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A before and after metric with dates</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">The raw material of every rate increase you will ever ask for.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Your invoice template with terms</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Late-payment terms written down before anyone is late are the cheapest protection available.</p></li></ul></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":""},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"border-y border-line bg-paper-2/70 py-14 sm:py-20"},{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"red-flags\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Walk away when you see these</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Not every one of these is a scam. Some are just clients who will cost you more than they pay you, which ends the same way.</p><ul class=\"mt-7 space-y-3\"><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Every single invoice comes back with questions</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">One dispute is a misunderstanding. A pattern is a payment strategy, and evidence will not fix it.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>\"Can you just do this quickly\" three times a week</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Unpriced work presented as trivial. It is the most common way a $9 rate becomes a $5 one.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>A trial rate with no written end date</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">That is not a trial, that is your rate. Get the second number and the date in writing on day one.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Praise instead of payment</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">\"You're amazing, we couldn't do this without you\" arriving in place of a raise is a known and cheap substitution.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>They want to pay monthly in arrears with no contract</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You are lending a stranger a month of labour. Weekly or biweekly for anyone new.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>They ask you to lower your rate because of your location</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Your cost of living is not a discount they earned. The work is worth what it is worth to their business.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>The scope grows every month and the fee never does</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Two years of this is how skilled people end up at an effective rate below where they started.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>They refuse both time tracking and output-based pricing</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">They have rejected every possible way of agreeing what you are owed. That is the whole answer.</p></li></ul></section></div><section id=\"faq\" class=\"scroll-mt-32 border-t border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Questions people actually ask</h2><div class=\"mt-7 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Is it really true that raising rates rarely loses clients?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Mostly. The consistent guidance across freelance pricing sources is that a well-communicated increase with notice loses only a small minority, and the extra revenue from everyone else covers it. That said, expect to lose someone eventually. That is the cost of having a price at all, and it is much cheaper than three years of not raising it.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Should I charge more because I work graveyard hours?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Yes, and say so plainly. Unsociable hours are one of the four legitimate factors. \"Covering 6am to 10am Pacific means 9pm to 1am here, which is priced in\" is a completely normal sentence in a quote.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">What if I am genuinely slow because I am still learning?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Then quote per output or cap the hours while you learn, so the client is not funding your training and you are not resenting the rate. Do not solve it by cutting your hourly, because that number is very hard to move back up later.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">The client says my rate is high for the Philippines. What do I say?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">\"The work is priced against what it is worth to your business, not against where I live.\" Then move straight to scope. Arguing about geography is a fight you cannot win and do not need to have.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Should I put my rate on my profile?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Yes, at the bottom of the range you will accept. It filters out the people who were never going to pay it, and it stops every negotiation opening with a number someone else chose.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">How often should I raise?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Review every six months, raise when the evidence supports it, and at minimum move with the market once a year. The people stuck at their starting rate are almost never the ones who asked and were refused. They are the ones who never scheduled the review.</p></details></div><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">Where the facts in this course came from</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">All free, all worth your time. Open them in another tab and check us.</p><ul class=\"mt-5 space-y-2.5\"><li><a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">OnlineJobs.ph salary guide</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The Philippine benchmark worth quoting. April 2026 figures by role and experience level.</span></a></li><li><a href=\"https://old.reddit.com/r/buhaydigital/comments/1vez4si/my_boss_keeps_saying_my_3_hours_of_work_is_only/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">r/buhaydigital: my boss keeps saying my 3 hours is worth 1 hour</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The thread behind module 9. Read the top comment and the output-pricing suggestion.</span></a></li><li><a href=\"https://earnifyhub.com/finance-money/freelance-pricing-rate-setting-framework-2026\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Freelance rate-setting framework, 2026</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Target-income-backward math and rate increase scripts. Skim the fluff, keep the notice-period guidance.</span></a></li><li><a href=\"https://www.memtime.com/blog/flat-rate-retainer-vs-hourly-rate\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Flat rate and retainer vs hourly</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Clear explanation of what a retainer actually obliges each side to do.</span></a></li><li><a href=\"https://toggl.com/track/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Toggl Track</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free tier</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Independent time logging. The evidence base for every pricing decision in this track.</span></a></li></ul></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-16\"><div class=\"rounded-2xl border border-line bg-clay-wash/60 p-7 sm:p-9\"><h2 class=\"font-display text-[1.5rem] font-semibold text-ink\">Finished? Go and use it.</h2><p class=\"mt-3 max-w-lg text-[0.9375rem] leading-relaxed text-ink-2\">The board updates every 30 minutes. Filter for this specialization, check your number against the rate tool, and send five tailored applications rather than fifty copy-pasted ones.</p><div class=\"mt-6 flex flex-wrap gap-3\"><a class=\"btn btn-primary\" href=\"/jobs\">See jobs on the board</a><a class=\"btn btn-ghost\" href=\"/pricing-tool\">Check your rate</a></div></div><div class=\"mt-10\"><p class=\"eyebrow text-muted\">Other written tracks</p><ul class=\"mt-3 flex flex-wrap gap-2.5\"><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/executive-assistant\">Executive Assistant</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/seo-specialist\">SEO Specialist VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/social-media-manager\">Social Media Manager VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/real-estate-va\">Real Estate VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/ecommerce-va\">E-commerce VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/complete-va-starter\">The Complete VA Starter</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/applications-that-get-replies\">Applications That Get Replies</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/becoming-an-ops-lead\">Becoming an Operations Lead</a></li></ul></div><a class=\"btn btn-ghost mt-8\" href=\"/courses\">← All courses</a></div><!--$--><!--/$-->"}],"modules":[{"n":1,"title":"What you are actually selling","outcome":"You can price a scope instead of a title, and you know which four factors legitimately move a number.","badges":["Time split","Red/green flags"],"minutes":22,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Nobody buys hours. They buy a result on a schedule with somebody responsible for it. Hours are just the billing unit you both agreed to pretend in.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Four things justify a higher number: scope, schedule, responsibility, and risk. Broader work, tighter or unsociable hours, more decisions you make alone, and more damage if you get it wrong.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Your years of experience are not on that list. Neither is your need. Clients pay for their own upside, not your circumstances.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Price the version of the job that exists, not the title. \"Executive assistant\" ranges from calendar tidying to running a founder's week, and those are not the same product.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never quote before you can list the outputs. If you cannot write six bullet points describing what appears each week, you are guessing.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The same work is worth more to a business with higher stakes. Chasing invoices for a company with $2m in receivables is not the same job as doing it for one with $20k.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Two quotes for the same job title</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Virtual assistant, 20 hours a week, $6/hr. General admin support.\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Scope: inbox triage daily by 9am PT, class schedule maintained across 3 studios, weekly instructor payroll sheet, member complaint first response within 2 hours, Friday summary report.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Schedule: 6am to 10am Pacific, five days, which is 9pm to 1am my time.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Responsibility: I answer members directly under the studio's name, and I sign off the payroll sheet before the owner approves it.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Risk: an error in the payroll sheet costs them real money and an instructor's trust.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Quote: $9/hr, 20 hours weekly retainer, invoiced biweekly. Additional projects quoted separately.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Nothing changed about the person. The second version is priced because the four factors are visible, and a client can see what they are paying more for.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Where the hours go</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What a client is actually paying for</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Rough weighting of where the value sits in a mature VA relationship. Beginners think it's all the first slice.</p><div class=\"mt-4\"><div class=\"flex flex-col items-center gap-5 sm:flex-row sm:items-start sm:gap-7\"><svg viewBox=\"0 0 140 140\" class=\"h-[8.5rem] w-[8.5rem] shrink-0 -rotate-90\" role=\"img\" aria-labelledby=\"_R_b1lanpfiuqbtb_\"><title id=\"_R_b1lanpfiuqbtb_\">Judgment: deciding what matters 30%, Reliability: it happens without asking 25%, Execution: the actual tasks 20%, Context: knowing their business 15%, Documentation and systems 10%</title><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"var(--color-line)\" stroke-width=\"20\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#097769\" stroke-width=\"20\" stroke-dasharray=\"105.55751316061705 246.30086404143978\" stroke-dashoffset=\"0\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#5fd0bf\" stroke-width=\"20\" stroke-dasharray=\"87.96459430051421 263.89378290154264\" stroke-dashoffset=\"-105.55751316061705\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#075f55\" stroke-width=\"20\" stroke-dasharray=\"70.37167544041137 281.48670176164546\" stroke-dashoffset=\"-193.52210746113127\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#4453b8\" stroke-width=\"20\" stroke-dasharray=\"52.778756580308524 299.0796206217483\" stroke-dashoffset=\"-263.89378290154264\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#e07a2f\" stroke-width=\"20\" stroke-dasharray=\"35.18583772020568 316.6725394818511\" stroke-dashoffset=\"-316.6725394818512\"></circle></svg><ul class=\"w-full space-y-2\"><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#097769\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Judgment: deciding what matters</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">30%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Knowing which email needs them and which doesn't. Impossible to commoditise.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#5fd0bf\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Reliability: it happens without asking</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">25%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The reason clients stay for years. Boring, and the most valuable thing you sell.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#075f55\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Execution: the actual tasks</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">20%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">What beginners think is 100% of the job. It's a fifth.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#4453b8\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Context: knowing their business</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">15%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Compounds monthly. It's also your best argument at every rate review.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#e07a2f\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Documentation and systems</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">10%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Turns your work into an asset that survives you. Charge for it.</p></li></ul></div><p class=\"mt-4 border-t border-line pt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Only a fifth of what you're paid for is the task itself. Price the other four-fifths and your rate stops being comparable to anyone else's.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">How you describe what the client is buying</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I charge $6 an hour for admin support. I can do data entry, email management, scheduling, research — whatever you need doing.\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">You've priced your TIME doing TASKS. Time is a commodity and tasks are comparable, so the only lever left is who's cheapest. There is always someone cheaper, and there always will be.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"For $900 a month I make sure nothing you've committed to gets dropped. That's your inbox held under 10, every meeting with an agenda and a decision log, and a chase list so the things people owe you actually arrive. You'd get roughly two mornings a week back.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">You've priced an OUTCOME. There's no direct comparison shopping for \"nothing gets dropped\", and the client is now weighing your price against the cost of the problem, not against another VA's hourly rate.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A client says another VA quoted less</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Oh — I could probably match that, or come down a bit. What were you thinking?\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">You've confirmed your price was arbitrary. If it drops the moment it's questioned, it was never real, and the client now knows to question everything else you say too.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"They might well be cheaper — plenty of people are. What I'd check is what happens in month three. My rate includes the documentation, so if I'm sick or I leave, the work doesn't stop. If budget's genuinely the constraint, I'd rather narrow the scope than cut the rate — same quality, less of it. Want me to price a smaller version?\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Doesn't disparage the competition, reframes on value, and offers a real path forward that protects your rate. Cutting scope is always better than cutting price, because price cuts are permanent.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Take a live job post in your lane and write out its scope, schedule, responsibility, and risk. Then write the same for the version you would actually want to be hired into.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A two-column comparison with a defensible rate for each column.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The scope column lists outputs with a frequency, not duties</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The schedule names your local hours, not just theirs</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You identified what breaks if you make a mistake</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The two rates differ and you can say why in one sentence</span></label></li></ul></div>"},{"n":2,"title":"Your floor","outcome":"You know the number below which work costs you money, calculated from your real life rather than from vibes.","badges":["Rates","1 template"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Work backwards from what your life costs, not forwards from what you hope someone pays. Total monthly needs, plus savings, plus tax, divided by billable hours.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You do not have 160 billable hours a month. Between admin, client calls, learning, applications and rest you are realistically selling 100 to 130.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Add tax. As a self-employed Filipino you owe it whether or not it is withheld, and pretending otherwise is a loan from your future self at a bad rate.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Add fees. Transfer and FX costs of 1 to 4 percent are real money and they come off the top.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Add an equipment and downtime allowance. Laptops die and typhoons happen, and your client's budget will not cover either.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Your floor is not your price. It is the line below which you are volunteering. Your price sits above it with room for the parts you did not predict.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Bexley scenario: floor calculation</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Monthly needs: ₱42,000 living, ₱6,000 savings, ₱2,500 equipment and downtime fund. Total ₱50,500.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Tax allowance at 8 percent of gross: budget roughly ₱4,400 on a ₱55,000 gross target.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Payment fees at about 2 percent: roughly ₱1,100.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Gross needed: about ₱56,000 a month, which at ₱57 to the dollar is roughly $980.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Realistic billable hours: 110 a month, not 160.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Floor: $980 divided by 110 equals about $8.90 an hour. Round the floor to $9.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Current rate: $6, at 80 hours a month, is $480. That is not a low rate, that is a shortfall of half a life.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The gap was never a negotiation problem. It was invisible because nobody had done the division. Once you have the floor, saying no becomes arithmetic instead of courage.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Working out your actual floor</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Your floor is not what you'd like to earn. It's the number below which working is worse than not working. Calculate it once and it becomes the thing you can't be talked below.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Monthly living costs</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">Your real number</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">₱[your total]</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Rent, food, power, internet, transport, family support, debt. Be honest, include everything.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">+ Business costs</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">~₱2,000–4,000/mo</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Internet, tools, power, equipment fund</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You pay for the office. Employees don't. This must be in the number.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">+ No-benefits premium</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">+20–30%</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Sick days, holidays, 13th month, SSS/PhilHealth/Pag-IBIG</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You get none of these. A freelancer at the same headline rate as an employee is paid less.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">+ Unpaid time</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">÷ 0.7</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Admin, applications, invoicing, learning</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Roughly 30% of your working week is unbillable. Your billable hours carry all of it.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">= Your floor</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">The result</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Never go below it</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Below this you're paying for the privilege of working. Say no, every time.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Worked example: ₱35,000 living + ₱3,000 business = ₱38,000. Add 25% for no benefits = ₱47,500. At 120 billable hrs/month that's ₱396/hr ≈ $6.80/hr. That's a FLOOR, not a target.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Floor calculator</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Do the arithmetic once, write the number down, and never negotiate below it. Knowing it is what makes saying no possible.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>STEP 1 — MONTHLY LIVING COSTS (be honest, not aspirational)\nRent / housing                    ₱______\nFood and groceries                ₱______\nElectricity                       ₱______\nWater                             ₱______\nInternet                          ₱______\nMobile load / data                ₱______\nTransport / fuel                  ₱______\nFamily support / allowances       ₱______\nLoan / debt repayments            ₱______\nInsurance / health                ₱______\nChildcare / school fees           ₱______\nEverything else (be realistic)    ₱______\n                    LIVING TOTAL  ₱______  (A)\n\nSTEP 2 — BUSINESS COSTS\nInternet upgrade over personal    ₱______\nSoftware and subscriptions        ₱______\nEquipment fund (laptop ÷ 24 mo)   ₱______\nPower for working hours           ₱______\nCoworking / backup location       ₱______\n                 BUSINESS TOTAL   ₱______  (B)\n\nSTEP 3 — THE THINGS EMPLOYEES GET AND YOU DON'T\nTake (A + B) and add 25%.\nThis covers: sick days, holidays, 13th month, SSS, PhilHealth, Pag-IBIG,\nand the months a client disappears with no notice.\n                       SUBTOTAL   ₱______  (C = (A+B) × 1.25)\n\nSTEP 4 — BILLABLE HOURS, NOT WORKING HOURS\nYou will not bill 160 hours a month. Applications, invoicing, admin,\nlearning and gaps between clients eat roughly 30%.\nRealistic billable hours per month: ______ (D)  [use 110–130 if unsure]\n\nSTEP 5 — YOUR FLOOR\nC ÷ D = ₱______ per hour\n÷ 58 (approx USD rate) = $______ per hour     ← YOUR FLOOR\n\nSTEP 6 — YOUR TARGET\nFloor × 1.5 = $______ per hour                ← what you actually quote\nThe gap between floor and target is your savings, your growth, and your\nability to walk away from a bad client. Without it you're trapped.\n\nWRITE YOUR FLOOR HERE: $______\nRules:\n• Never quote it. Quote your target.\n• Never accept below it. Not \"just to get started\". Not \"just this once.\"\n• Recalculate every 6 months, and every time your costs change.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build the floor calculator in Sheets with your real numbers. Include tax, fees, savings, and an equipment fund.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A sheet that outputs one number: your hourly floor, with billable hours as an adjustable input.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Billable hours are under 130 a month</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Tax and payment fees are separate line items</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">There is a savings line, not a leftover</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You compared the floor to what you currently earn per hour</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The sheet recalculates when you change one input</span></label></li></ul></div>"},{"n":3,"title":"Reading the market without racing to the bottom","outcome":"You can place yourself in a real band using evidence, and you can say why you sit above the average.","badges":["Workflow","Red/green flags"],"minutes":24,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The most useful Philippine benchmark is the OnlineJobs.ph April 2026 salary guide. General VA local hourly runs roughly $3 to $5 beginner, $6 to $9 intermediate, $10 to $12 expert, with specializations sitting higher.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A benchmark describes what is being paid, not what is fair and not what you must accept. Treat it as the weather, not the law.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The band you belong in is set by evidence, not by time served. Can you show a metric you moved, an SOP you wrote, a decision you made alone.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do not price against other Filipino VAs. Price against what solving the problem is worth to that business, then sanity-check against the band.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Watch the ceiling, not just the floor. If nobody in your lane earns above $12, you are in a lane with a lid, and the fix is a different lane rather than a better argument.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Rates for the same title vary wildly by client type. Agencies pay least and place fastest. Direct US small businesses pay more and require more of you. Funded startups pay most and churn hardest.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Placing yourself with evidence</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"I've been a VA for 2 years so I think I'm intermediate. Maybe $7?\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Evidence 1: I own the class schedule across three studios with no oversight. Nobody checks it. That is intermediate to expert on responsibility.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Evidence 2: I cut member complaint first-response time from about a day to under two hours, measured over eight weeks.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Evidence 3: I wrote the four SOPs the owner now uses to train new front-desk staff.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Evidence 4: I cover 6am to 10am Pacific, which is 9pm to 1am for me. Unsociable hours are a priced factor, not a favour.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Placement: top of intermediate, entering expert, so $9 to $10. I will ask $9 because the scope is defined and I want the increase agreed rather than debated.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Four lines of evidence turn \"I think I deserve more\" into a position. You are not asking them to be generous, you are asking them to be accurate.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Reading the market without racing to the bottom</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Before setting or changing your rate. Once a quarter.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Pull 20 live posts in your exact lane</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Verse's board, Upwork, OnlineJobs.ph. Your lane specifically, not \"VA\" generally — the general number is always lower and it's not your market.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Write down the range, ignore the average</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The average is dragged down by the desperate posts. What matters is the top quartile, because that's who you're trying to work for.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Separate the tiers hiding in the same title</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"Ecommerce VA\" covers $3 uploads and $15 PPC management. Work out which tier each post is actually buying, then compare like with like.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Check what the top-paying posts require</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">That's your development plan. If every $12 post wants Klaviyo, you now know what to learn this quarter.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Position at the 60–75th percentile, not the middle</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Above average, below premium. You'll lose the bargain hunters, which is the point — they're the clients who cause the most trouble anyway.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Sanity-check against your floor</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">If the market's 75th percentile is below your floor, the lane is wrong or the market is wrong, and you need to change one of them.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Setting your rate by asking other VAs in a Facebook group. You'll get a chorus of underpriced people validating each other. Look at what employers are POSTING, not at what your peers accepted.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">How you think about competing on price</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"There are so many Filipino VAs now. If I don't charge $4, someone else will, and I'll never get hired.\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Partly true and completely unhelpful, because it assumes clients only compare on price. The clients who choose purely on price are also the ones who scope-creep, pay late and churn in three months. Winning them is a loss.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I'll lose the clients whose only question is the rate. I'm competing for the ones who've already been burned by a cheap hire and now care more about not repeating it. There are fewer of them and they pay double.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">There are two markets sharing one job board. The cheap one is enormous, crowded and miserable. The other is smaller, quieter, and the only way into it is refusing to compete in the first one.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Collect ten current job posts in your lane, record the posted rate or salary, then write your own evidence list against the band.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A rate research sheet plus a four-point evidence list placing you in a band.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">At least seven of the ten posts include a stated rate or range</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You noted the client type for each, agency or direct or startup</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Every evidence point references something observable</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You named the band and the specific number you will ask for</span></label></li></ul></div>"},{"n":4,"title":"Choosing the model","outcome":"You can pick between hourly, retainer, per-output and project pricing based on which one protects you in that specific situation.","badges":["Tools","Rates"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Hourly is honest and has a hard ceiling. You get paid for what you do and you get punished for getting faster.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Retainer means the client pays to reserve capacity, for example 20 hours a week, whether or not they use it. Predictable for both sides, and it needs a written rule for unused and overflow hours.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Per-output pricing bills the deliverable: $10 per post, $40 per blog, $2 per lead cleaned. It rewards speed and it ends every argument about how long something took.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Project pricing suits one-off builds with a defined end. Always attach a revision limit or you have invented an unpaid retainer.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Choose the model that neutralises the specific risk in front of you. Client disputes your hours: go per-output. Client's volume is unpredictable: go retainer with an overflow rate. Scope is genuinely unknown: hourly with a cap.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You can change model at renewal. \"From September I would like to move to a monthly retainer so your costs are predictable\" is a normal, unremarkable request.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Same $1,200 a month, four ways</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Hourly: $9 x 33 hours. You are paid for effort. Every efficiency you invent costs you money.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Retainer: $1,200 for up to 35 hours a month, unused hours expire, overflow at $12. Predictable income, protected downside.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Per-output: 30 posts at $40. Speed becomes profit. Requires a very tight definition of one post.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Project: $1,200 to build and hand over the whole content system, two rounds of revisions, four weeks.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Which to pick for Bexley: retainer. Their volume swings weekly and they are the type to describe extra work as \"quick\".</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The model is a risk allocation, not an accounting preference. Ask what could go wrong here, then pick the model where that thing costs you least.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Pricing models, and when each one wins</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Most VAs use hourly forever because it's the default, not because it's right. Moving off hourly is usually the single biggest raise available to you.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width: 52rem;\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Hourly</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Unclear scope, new clients, and work that genuinely varies week to week.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">You keep none of the upside</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Fine to start. Its fatal flaw: getting faster earns you LESS. You're punished for competence.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Monthly retainer</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Ongoing work with a stable scope. Most VA relationships.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Predictable both ways</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The default you should aim for. Predictable income for you, predictable cost for them, and you keep the gains as you get faster.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Package / tiered</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Selling to new clients. Three named options.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — needs clear scope</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Higher effective rate</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Best conversion tool there is. Three tiers changes the question from \"should I hire?\" to \"which one?\" Most people pick the middle.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Per project / per deliverable</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Countable outputs: listings, articles, audits, videos.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — you must estimate well</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">You keep all the speed gains</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Excellent once you know how long things take. Underprice the first few deliberately as tuition, then raise it.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Value / outcome-based</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Work with a direct, traceable revenue line.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Hard</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Highest ceiling, highest risk</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Rare in VA work and often overhyped. Only viable when you genuinely control the outcome — otherwise you're gambling on someone else's business.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Retainer + performance bonus</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">ISA work, sales support, anything with a countable win.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Base covers the floor, bonus is upside</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The underrated option. A liveable base plus $50/appointment aligns you with the client without betting your rent on it.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Package structure that converts</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Three tiers, priced so the middle one is obviously the sensible choice. This is deliberate, and it works because it changes what the client is deciding.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width: 38rem;\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Starter (the anchor at the bottom)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">10 hrs/wk</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$400–500</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Deliberately narrow. Exists mainly to make the middle tier look reasonable.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Core (the one you want them to buy)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">20 hrs/wk</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$800–1,100</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The most complete-looking value. Roughly 60–70% of clients choose this.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Full (the anchor at the top)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">40 hrs/wk</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,600–2,400</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Makes Core look modest. Some clients genuinely take it, which is a bonus.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Add-ons</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">Priced separately, always</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$100–400 each</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Where your margin lives. Never fold these silently into a tier.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Rush / out of hours</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">1.5× base</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Billed on top</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Write it into the contract on day one, not the first time it happens.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Always present three. One price is a yes/no decision, which is easy to refuse. Three prices is a which-one decision, and most people answer the question you actually asked.</p></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write your current or target engagement as all four models at the same total, then name the risk each one protects you from.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A four-row comparison with a recommendation and one sentence of reasoning.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The retainer row states what happens to unused and overflow hours</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The per-output row defines exactly what one unit includes</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The project row has a revision limit</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You named a specific risk for each, not a general preference</span></label></li></ul></div>"},{"n":5,"title":"Quoting out loud","outcome":"You can deliver a number in a live conversation without hedging, discounting, or filling the silence.","badges":["Workflow","1 template"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The structure is scope, then number, then cadence, then silence. \"For the scope in your post, around 20 hours a week, my rate is $9 an hour and I invoice biweekly.\"</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Then say nothing. The pause is unbearable and it is the entire technique. Whoever speaks first usually concedes something.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never answer \"what's your rate\" with \"what's your budget\". You have just told the client the price is whatever they say. You do not recover from it in the same conversation.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">If they ask for a range, the top of your range is the only number they will remember. Quote the range you would be happy with at the bottom.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Quote in writing after the call, within an hour, with the scope restated. Verbal agreements decay into whatever each person wanted to hear.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do not itemise your reasoning unprompted. Explaining a price before anyone objects sounds like you expect to be argued down.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Four openings, one that works</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"I'm flexible, whatever your budget allows.\" You have set the price at their number.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"My rate is usually $9 but I can do $7 to start.\" You discounted before anyone objected.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Somewhere between $6 and $12 depending on the work?\" They heard $6 and stopped listening.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"For the scope in your post, around 20 hours a week covering the inbox, the schedule and the weekly report, my rate is $9 an hour and I invoice biweekly.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">[Silence. Count to ten in your head. Do not fill it.]</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">If they accept: \"Great. I will send the scope in writing within the hour so we are both looking at the same list.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">If they hesitate: \"What part of that feels off, the number or the scope?\" Now they are diagnosing with you rather than negotiating against you.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">\"The number or the scope\" is the most useful question in this track. It converts a rejection into two options, and one of them is a smaller job at your rate.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Quoting out loud without flinching</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The moment in every call where they ask what you charge.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Get the scope before you get to the number</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"Before I give you a figure — can I check a couple of things about what's involved?\" Quoting blind is how you end up underpriced or wrong.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Say the number, then STOP TALKING</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The hardest and most important skill here. Say \"$900 a month\" and then be silent. Every word you add after the number is a discount.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Let the silence sit</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Three seconds feels like a minute. They're thinking, not rejecting. Whoever speaks first usually concedes something.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">If they react, ask rather than adjust</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"What were you expecting?\" not \"I could do less\". You need the information before you decide anything.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Move scope, not price</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"For $600 I'd drop the reporting and the community management — same quality, less of it.\" Your rate stays intact and they still get a yes.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Be willing to end it warmly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"Sounds like we're too far apart, which is completely fine. If your budget changes, I'd be glad to talk.\" The ability to walk is what makes the number real.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Filling the silence after your number with justification. \"...but I'm flexible, and I know that might seem like a lot, and we could maybe start smaller...\" You just negotiated against yourself before they said a word.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The quoting script</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Say each of these out loud twenty times before your next call. It has to be boring in your mouth.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>WHEN THEY ASK EARLY, BEFORE YOU KNOW THE SCOPE\n\"Happy to talk numbers — can I ask two quick things first so I quote you something real rather than a range? [Question about volume]. [Question about what's included.]\"\n\nTHE QUOTE ITSELF\n\"For what you've described, that's my Core package — $900 a month. That covers [3–4 specific things], 20 hours a week.\"\n\n[STOP. Say nothing. Count to five in your head. Let them speak next.]\n\nIF THEY SAY IT'S MORE THAN THEY EXPECTED\n\"That's fair — what were you expecting?\"\n[Then listen to the whole answer before responding.]\n\nIF THE GAP IS SMALL (under ~15%)\n\"I can work with that if we [remove one specific thing]. Otherwise the rate's the rate.\"\n\nIF THE GAP IS LARGE\n\"We're a fair distance apart. Two honest options: I can put together a smaller scope that fits $[their number] — probably [reduced version]. Or we leave it, no hard feelings, and if the budget moves later I'd be glad to pick it up. Which would you prefer?\"\n\nIF THEY ASK FOR A DISCOUNT FOR NO REASON\n\"I keep my rates the same for everyone — it's simpler and it means nobody's subsidising anyone else. What I can do is [smaller scope / a shorter trial period] if you want to test it first.\"\n\nIF THEY WANT A FREE TRIAL\n\"I do paid trials — a small real task, at my normal rate, so you can see how I work with no long commitment. Usually [n] hours, $[n]. Best way for both of us to find out.\"\n\nIF THEY GO QUIET AFTER THE NUMBER\n[Say nothing. Genuinely nothing. If it stretches past ~8 seconds:]\n\"Happy to talk through what's driving that number if it'd help.\"\n\nPRACTISE RULE\nSay your rate out loud to a wall, twenty times, until it sounds boring.\nIf it still feels like a confession when you say it, it will sound like one.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Record yourself on Loom quoting three different scopes out loud, including the silence. Watch it back.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: One Loom under five minutes with three quotes and a written note on where your voice went up at the end.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 35 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You stated a specific number in all three</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You did not apologise or laugh after saying it</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You held the silence for at least five seconds each time</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">None of the three ended in a question mark</span></label></li></ul></div>"},{"n":6,"title":"Objections","outcome":"You can handle the six standard pushbacks without discounting, by moving scope instead of price.","badges":["Red/green flags","1 template"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The default response to every objection is the same: reduce the scope, keep the rate. Discounting teaches the client that your first number was decoration.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">\"Too expensive\" often means \"I cannot see what I get\". Answer with the deliverables list before you answer with money.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">\"Other VAs charge $3\" is a real fact about the market and an invitation to compete on being the cheapest, which is a race you win by losing. Reply with the difference in what is included, then let them choose.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">\"Can we start at a lower trial rate?\" Fine, if it has a date and a written number for what happens after. A trial rate with no end date is just your new rate.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">\"We'll increase it once we see results\" needs the trigger written down: which result, measured how, reviewed on what date.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">\"We can't afford that\" may be true. Offer a smaller shape of the job. If the smallest useful version is still unaffordable, they are not a client yet, and that is information rather than rejection.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Six objections, six replies</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"That's more than we budgeted.\" - \"Understood. At $7 I would keep the inbox and the weekly report and drop the schedule maintenance, since that is the piece that eats hours. Which shape works better for you?\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Other VAs charge $4.\" - \"They do, and for pure data entry that is the right price. What you are describing includes answering members under your name and signing off payroll. Happy to quote the data-entry-only version if that is closer to what you need.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Can you do a lower trial rate for a month?\" - \"Yes: $7 for the first four weeks, then $9 from 1 October, in writing now. I would rather agree the second number today than negotiate it again in a month.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"We'll raise it once we see results.\" - \"Let's define that. If complaint first-response is under two hours for four straight weeks, the rate goes to $9 on the following invoice. Same sentence in the agreement?\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Can you match what we paid the last VA?\" - \"What did they cover? If it is the same list I can look at it. If they were doing less, the honest answer is that this is a bigger job.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"We just can't afford it right now.\" - \"Then here is the $500 a month version: inbox only, weekdays, no reporting. If it stops being useful either of us can end it with two weeks' notice.\"</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Not one of those replies lowers the hourly rate. Every one gives the client a real choice, which is why they do not feel like refusals.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">\"That's more than we budgeted\"</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Oh okay, no problem! What's your budget? I'm sure we can make something work — I really want to work with you.\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Instant collapse. You've said your price was fake, and \"I really want to work with you\" hands them all the leverage in every future conversation too, not just this one.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"What is the budget? … Okay, $600. At that level I'd do the inbox and calendar only, and drop the meeting prep and the reporting. That's a real version of this that works at $600. Or if you need the whole scope, $900 is what it takes. Both are fine with me — which suits you better?\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Asks for their number, then offers two genuine options at different scopes. You've held the rate, given them agency, and stayed relaxed. Relaxed is the whole trick.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">\"We can offer more work later if you start lower now\"</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Accepting, because more work later sounds like a good deal and you want the client.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">The promise is almost never kept, and when it is, the low rate is now your established price and raising it becomes a fight. You've paid for future work that may not exist, with a permanent discount.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I'd rather do it the other way round — start at my rate with a smaller scope, and grow the scope as it proves out. That way you're not committing to much and I'm not starting somewhere I can't sustain. Same first-month cost to you, honestly.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Gives them the low commitment they actually wanted, without setting a low rate. Small scope at a full rate always beats full scope at a small rate.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">\"I can get someone on OnlineJobs.ph for $3/hour\"</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Yes, but they won't be as good as me.\" Or panicking and matching it.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">The first is unprovable and sounds defensive. The second destroys your pricing permanently and attracts exactly the client who'll do this again next quarter.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"You absolutely can, and some of them are very good. The thing I'd check is what happened last time — most people asking me this have already tried a $3 hire and it cost them more in rework and management than the saving. If it worked out, honestly, do that. If it didn't, that's the difference you'd be paying for.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Agrees with the true part, doesn't insult anyone, and points at their own experience rather than your opinion. Most people asking this question have already been burned, and you've just let them remember it themselves.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Objection responses</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Learn the shape, not the script. All of them follow: acknowledge → ask or reframe → offer a real choice.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>\"THAT'S TOO EXPENSIVE\"\n\"What were you expecting? … Right. At $[theirs] I'd scope it as [reduced]. At $[yours] you get [full]. Both work for me.\"\n\n\"CAN YOU DO IT CHEAPER?\"\n\"Not at this scope, no. I can do less at a lower price if that helps — what would you drop first?\"\n[Making THEM choose what to cut usually reveals it was all necessary.]\n\n\"WE'LL START LOW AND INCREASE IT LATER\"\n\"I'd rather start small and grow the scope. Same first-month cost, and neither of us is locked into a number that doesn't work.\"\n\n\"OTHER VAS CHARGE LESS\"\n\"They do. What did the last one cost you in rework?\"\n\n\"CAN YOU DO A FREE TRIAL?\"\n\"I do paid trials — [n] hours at my normal rate on something real. You'll learn more from that than from a free sample anyway.\"\n\n\"WE'RE A STARTUP / IT'S FOR A GOOD CAUSE\"\n\"I get it, and I'd like to help. I can't do that on rate, but I can do a smaller scope, or a 3-month intro period at [modestly reduced] with the full rate after. Would either work?\"\n[Give a discount with an END DATE or don't give one at all.]\n\n\"CAN YOU BILL LESS HOURS BUT DO THE SAME WORK?\"\n\"No. But tell me what the constraint is and I'll find you a real way to hit it.\"\n[This is a request to be defrauded, politely. Never agree.]\n\n\"WHAT'S YOUR BEST PRICE?\"\n\"The one I gave you. I don't have a haggling rate — it'd mean the first number was dishonest.\"\n\n\"LET ME THINK ABOUT IT\"\n\"Of course. Anything I can clarify while you do? … I'll follow up on [day] if I haven't heard, just so it doesn't drift.\"\n\nTHE THREE RULES BEHIND ALL OF THEM\n1. Never be offended. Negotiating is their job, not an insult.\n2. Never cut price without cutting scope. Ever.\n3. Be genuinely willing to hear no. It's what makes everything above believable.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write your own version of all six replies in your own voice and lane. Then have a friend read the objections to you out loud while you answer live.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page objection script plus a note on which one you fumbled.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">No reply lowers the rate without removing something</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Every conditional promise has a date and a measurement</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Nothing you wrote contains the word sorry</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Each reply ends with a question or a clean choice</span></label></li></ul></div>"},{"n":7,"title":"Scope creep and the change request","outcome":"You can absorb the small stuff deliberately and price the rest, without becoming the person who invoices for everything.","badges":["Workflow","3 templates"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Scope creep is rarely malicious. It is a busy person handing the nearest capable human whatever is on fire.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Have a written line. Under 15 minutes and related to your existing work: absorb it, mention it once in the weekly summary so it is visible. Anything larger: change request.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The change request is three sentences. This is outside what we agreed, here is the time or cost, please confirm and I will start.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Send it before you do the work, always. Afterwards it is a bill, and bills people did not expect are how relationships end.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keep an absorbed-work log. At review time, \"here are 31 hours of extra work I took on this quarter\" is the most persuasive document you will ever produce.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">If change requests keep getting approved, the scope is genuinely bigger than the contract. Renegotiate the retainer instead of running a permanent side-channel.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The change request, and the log it feeds</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Client, Thursday 4pm: \"Hey, can you also pull together the instructor certifications for all three studios? Should be quick.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">What most people do: say yes, spend six hours, feel resentful, say nothing.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Happy to. That one sits outside our current scope, and gathering and verifying certs across three studios is about six hours based on the last audit.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"That is $54 at our rate, or I can slot it into next week's retainer hours and push the Friday report to Monday. Which do you prefer?\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Confirm either way and I will start this afternoon.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Then the log entry: 14 Aug, instructor cert audit, 6 hrs, approved as retainer swap, report moved to Monday.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The client gets a choice between money and time, which is a normal business conversation. You get a dated record either way.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Catching scope creep before it's your whole job</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The third time something appears that wasn't in the agreement.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Track it from week one, quietly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A log of every out-of-scope request, when it arrived, who asked, hours spent. Without evidence this conversation is your feelings versus their memory.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Say yes to the first one or two, and NAME them</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"Happy to do this one — noting it's outside our scope so we can look at it if it becomes regular.\" Cheerful, not passive-aggressive. You've started the clock.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Raise it at 3–4 hours a week of extra, not at 15</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Waiting until you're drowning means the conversation happens while you're resentful, and resentment always leaks into the wording.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Present it as a choice, never a complaint</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Two options you'd both accept: expand the package, or hand something back. Not \"this isn't fair\".</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Update the written scope either way</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Whatever they choose, the document changes. An unchanged scope document means the same conversation in six weeks.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Reset the counter and keep logging</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Creep is continuous, not a one-off event. The log never stops.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Hoping they'll notice and offer more money. In nine years of anyone doing this work, no client has ever spontaneously said \"you seem to be doing more than we agreed, let me pay you extra\". You have to raise it.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Scope creep log</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Start it on day one, before there's a problem. It converts an emotional conversation into an arithmetic one.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Date</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">What was asked</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Who asked</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">In scope?</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Hrs</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Did it?</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Flagged?</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td><td class=\"px-3 py-2.5 text-ink-2\">Reconcile Stripe payouts</td><td class=\"px-3 py-2.5 text-ink-2\">Owner</td><td class=\"px-3 py-2.5 text-ink-2\">✗ bookkeeping</td><td class=\"px-3 py-2.5 text-ink-2\">1.5</td><td class=\"px-3 py-2.5 text-ink-2\">Y</td><td class=\"px-3 py-2.5 text-ink-2\">Y — noted as one-off</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 11</td><td class=\"px-3 py-2.5 text-ink-2\">Reconcile Stripe payouts</td><td class=\"px-3 py-2.5 text-ink-2\">Owner</td><td class=\"px-3 py-2.5 text-ink-2\">✗</td><td class=\"px-3 py-2.5 text-ink-2\">1.5</td><td class=\"px-3 py-2.5 text-ink-2\">Y</td><td class=\"px-3 py-2.5 text-ink-2\">Y</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 14</td><td class=\"px-3 py-2.5 text-ink-2\">Reply to customer emails</td><td class=\"px-3 py-2.5 text-ink-2\">Owner</td><td class=\"px-3 py-2.5 text-ink-2\">✗ support</td><td class=\"px-3 py-2.5 text-ink-2\">3.0</td><td class=\"px-3 py-2.5 text-ink-2\">Y</td><td class=\"px-3 py-2.5 text-ink-2\">N</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 18</td><td class=\"px-3 py-2.5 text-ink-2\">Reconcile Stripe payouts</td><td class=\"px-3 py-2.5 text-ink-2\">Owner</td><td class=\"px-3 py-2.5 text-ink-2\">✗</td><td class=\"px-3 py-2.5 text-ink-2\">1.5</td><td class=\"px-3 py-2.5 text-ink-2\">Y</td><td class=\"px-3 py-2.5 text-ink-2\">— now weekly</td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">RUNNING TOTAL THIS MONTH\nOut-of-scope hours: [n]\nAs % of contracted hours: [n]%\nRecurring items that have become permanent: [list]\n\nTRIGGERS FOR THE CONVERSATION\n• Over 10% of contracted hours in a month → mention it lightly\n• Over 20% → have the real conversation this week\n• Anything that has happened 3+ times → it isn't a favour any more, it's part of the job</pre></div></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The scope conversation</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Send when the log hits your trigger. Calm, evidenced, two acceptable outcomes.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Hi [name],\n\nWanted to flag something before it becomes awkward, because it's an easy fix.\n\nOur agreement covers [scope items]. Over the last [n] weeks I've also been doing:\n• [Item] — roughly [n] hrs/week, since [date]\n• [Item] — roughly [n] hrs/week, since [date]\n\nThat's about [n] extra hours a week, or [n]% over what we agreed. I've been happy to absorb it while it was occasional, but it's now regular enough that it needs a decision rather than drifting.\n\nTwo options, both genuinely fine with me:\n\n1. Move to [next package] at $[n]/month, which covers everything I'm currently doing plus a bit of headroom.\n\n2. Keep the current package and I hand [specific item] back — either to you, or I can help you find someone for it.\n\nNo rush, but can you let me know by [date]? Happy to jump on a call if it's easier to talk through.\n\n[Your name]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Change request form</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">For anything new mid-contract. Turns \"can you just...\" into a decision with a price on it.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>CHANGE REQUEST — [date]\n\nRequested by: [name] on [date, channel]\n\nWHAT'S BEING ASKED FOR\n[Plain description, in their words where possible]\n\nIS IT IN SCOPE?\n[ ] Yes — proceeding, no action needed\n[ ] No — needs a decision\n\nIF OUT OF SCOPE\nEstimated time: [n] hours [one-off / per week]\nCost: $[n] [one-off / added to monthly]\nImpact on current work: [what gets delayed, honestly]\n\nOPTIONS\n1. Add it — $[n], starting [date]\n2. Swap it for [existing item] — no cost change\n3. One-off at $[n], not ongoing\n4. Don't do it\n\nMY RECOMMENDATION\n[Which, and why — one line]\n\nApproved: [ ] Option [n]   Signed: __________  Date: ______\n\n[Small, unfussy, and sent within an hour of the request. Doing this consistently\nis what stops you being the person things get quietly dumped on.]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write your change request template, then back-date an absorbed-work log for the last month of your real work, paid or unpaid.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A three-sentence template plus a log with at least five entries and an hours total.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 35 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The template offers a choice between paying and reprioritising</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">It asks for confirmation before you start</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The log has dates, hours, and whether it was approved</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You totalled the hours and converted them to money</span></label></li></ul></div>"},{"n":8,"title":"Asking for more from a client you already have","outcome":"You can run a rate increase as a scheduled, evidenced business conversation instead of an emotional ambush.","badges":["Workflow","Rates","2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Raising an existing client is the highest-return hour in your business. No applications, no interviews, no onboarding.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Give notice. Thirty to forty-five days before the new rate starts is the norm, and it turns the conversation from a demand into an announcement with a runway.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Lead with delivered value, not with your costs. Their electricity bill went up too, and it is not their problem.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do not apologise and do not over-explain. A rate increase is ordinary commercial behaviour, and treating it as an imposition invites them to agree with you.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Guidance across freelance pricing sources is consistent: well-communicated increases lose only a small minority of clients, and the increase from the rest more than covers it. Expect to lose someone eventually, and price that in.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">If they genuinely cannot pay, reduce scope rather than the rate. Same fee, fewer deliverables, protects your effective rate and your precedent.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The rate increase message, in full</p><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Subject: Rate change from 1 October</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Hi Dana,</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Quick note ahead of time so nothing is a surprise. From 1 October my rate moves from $6 to $9 an hour, which for our 20-hour week is $720 a fortnight instead of $480.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">The short version of why: the role now covers three studios instead of one, I answer members directly under the Bexley name, and I sign off the payroll sheet before you approve it. Complaint first-response is under two hours, down from about a day when I started, and the four SOPs I wrote are now what you train front desk on.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">September stays at the current rate, so this gives us six weeks. If the new number does not work for the budget, the alternative is keeping the fee where it is and narrowing the scope to inbox and reporting only, and I would drop the schedule and payroll work.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Happy either way. Let me know which you prefer by the 15th so I can plan.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Mika</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">It gives a date, evidence, an alternative, and a deadline for the decision. It never once asks permission to be paid more.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Asking an existing client for more</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Annually, or after you've taken on materially more. Never spontaneously in a bad month.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Build the evidence file over months, not the night before</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Keep a running note of every metric, every problem prevented, every thing you took over. Assembling it in one panicked evening produces a weak case.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Pick the timing deliberately</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Right after a visible win. Never during their cash crunch, never right after you made a mistake, never in the same week you asked for time off.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Give 60 days' notice, in writing</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">This is the professional move that separates a rate change from a demand. It gives them time to budget, which makes yes much easier.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Lead with evidence, then the number</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Three specifics with numbers, THEN the new rate. Reversing the order makes it a negotiation instead of a conclusion.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Offer the scope alternative up front</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"If the budget won't stretch, let's trim scope instead.\" It shows you're solving their problem too, and it makes refusal harder.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Know your walk-away before you send it</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Decide in advance what you'll do if they say no. If the answer is \"nothing\", they'll sense it, and it'll be a no.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Asking apologetically. \"I was wondering if maybe it might be possible to perhaps discuss a small increase?\" makes it easy to say no. State it as a decision you're giving them notice of, not a favour you're begging for.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">When to raise, and by how much</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Rate increases don't happen to you. They're something you schedule.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width: 38rem;\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Annual, no scope change</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">+8–15%</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Every 12 months</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Standard. Frame it as inflation plus a year of accumulated context.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">You took on materially more</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">+20–35%</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">When it happens</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Don't wait for the anniversary. Raise it when the scope changed.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">You added a real skill</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">+15–25%</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">On proof, not on completion</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">A certificate isn't proof. A result you produced with the skill is.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">New clients vs existing</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">+20–30% above your oldest</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Always</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Your longest client is always your cheapest. Price new ones at today's rate.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">They said no</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">Set a review date</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">3–6 months</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">\"Let's revisit in March\" — in writing. A no with no date is a permanent no.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">A VA who never raises rates takes a real-terms pay cut every year. Peso inflation doesn't pause because the conversation is uncomfortable.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The rate increase email</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">60 days' notice. Evidence first, number second, no apology anywhere in it.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Subject: Rate change from [date] — plenty of notice\n\nHi [name],\n\nWe hit a year this month, so I wanted to flag a rate change well ahead of time.\n\nQuick look at where we've got to since [start month]:\n• [Metric with a number. \"Inbox from 200+ daily to under 10, held there every day for 11 months.\"]\n• [Something you took over that wasn't in the original scope]\n• [A problem you prevented, or a process you built. \"Built the SOP set, so the work runs when I'm on leave.\"]\n\nFrom [date — 60 days out], my rate for this scope goes to $[new]/month, up from $[old]. That's a [n]% increase, and everything we currently do stays exactly as it is.\n\nIf that doesn't fit the budget, tell me and we'll look at trimming scope instead — I'd much rather adjust the work than end a good arrangement.\n\nLet me know either way by [date] so I can plan.\n\n[Your name]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">If they say no</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Don't accept a bare no. Convert it into a date, a condition, or a decision you make.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>IF IT'S A BUDGET PROBLEM (usually genuine)\n\"Understood. Two ways forward: I can reduce scope to fit the current rate — [specifically what I'd drop] — or we hold the rate and set a review for [3 months]. Which is easier for you?\"\n[Get the review date IN WRITING. A no with no date is a permanent no wearing a disguise.]\n\nIF THEY DISPUTE THE VALUE\n\"That's worth talking through properly — I'd rather know than guess. What's not landing for you at the moment?\"\n[Listen fully. Sometimes they're right and you have work to do. Sometimes they've simply never seen your output summarised, which is a reporting problem you can fix in a week.]\n\nIF THEY SAY \"MAYBE LATER\" WITH NO DATE\n\"Can we put a date on it? Say [month]. That way I'm not raising it every few weeks and you're not being asked out of the blue.\"\n\nIF IT'S A FLAT NO, TWICE, WITH NO REVIEW DATE\nThen you have your answer, and it isn't about money.\nDecide, calmly and on a timeline:\n• Stay at this rate and take the pay cut knowingly — sometimes correct, if the client is easy and stable\n• Reduce the hours here and use them for a better-paying client\n• Start looking, give notice properly, and leave well\n\nNever: stay, resent it, and let the work quality drop. That damages your reputation, not theirs.\n\nTHE THING TO REMEMBER\nA client who will never pay more is capping your income permanently.\nThat's a business decision they're allowed to make, and leaving is a business\ndecision you're allowed to make. Neither is a betrayal.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write the real version of this to your actual client, or your most likely future one. Then write the two replies you are most afraid of and your answer to each.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A rate increase message plus two pre-written responses to pushback.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">There is a specific effective date at least 30 days out</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The evidence is measurable, not adjectives</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The alternative reduces scope rather than the rate</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">There is a decision deadline</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The word sorry does not appear</span></label></li></ul></div>"},{"n":9,"title":"When the answer is to leave","outcome":"You can tell a hard negotiation from an unwinnable one, and exit professionally without burning the reference.","badges":["Red/green flags","2 templates"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Some clients are not negotiating, they are just not going to pay. The tell is that evidence changes nothing. When you have sent timestamps, screenshots and links and the answer is still no, the disagreement is not about facts.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Watch for the pattern: every invoice gets questioned, hours get shaved, praise arrives instead of money, and the scope keeps growing anyway.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never trade dignity for a reference. A client who disputes your hours will not write you a good one.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Before you leave, try one structural fix: move to output-based pricing. \"$10 per post\" ends the argument about how long a post takes. If they refuse that too, the issue was never measurement.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Leave properly. Notice period, handover doc, access returned, final invoice with terms. The market is small and your professionalism outlives the client.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build the conditions that let you leave: an emergency fund, more than one client, and no single client above half your income. Pricing power is mostly a function of not being trapped.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The exit that keeps your reputation</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Hi Dana, I have given this a lot of thought. We keep landing in the same disagreement about how long the work takes, and I do not think more evidence is going to resolve it.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"So rather than keep relitigating it, I am giving two weeks' notice. Last day 29 August.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"By then you will have: all SOPs in the shared Drive, a handover Loom for the schedule and payroll process, every access revoked from my side, and the final invoice for work through the 29th.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"No hard feelings on my side. I am glad to answer questions from whoever picks it up for a week after I finish.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">What you left out: the paragraph about how it made you feel. Correct. That paragraph is for your friends, not for the record.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">You can be completely done with someone and still leave them a clean desk. Those are the exits people remember when they refer you later.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Deciding whether to fire a client</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Staying for two more years because the money is steady, while dreading every message and letting the work quality slowly slide.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">The cost isn't just the misery. A bad client occupies the hours and the mental space a better one would need, so it blocks the replacement from ever appearing. And declining work quality damages your reputation, not theirs.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"This client is 30% of my income and about 70% of my stress. I'm giving it 60 days: I raise the rate, I enforce the scope document, and I fix the response-time expectation. If any of those fail, I give 30 days' notice and I fill the gap first.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">A decision with a deadline and a test, rather than a mood. And filling the gap first is the part people skip — leave from a position of having options, not from desperation.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">How you leave</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Ghosting. Or a furious final message listing every grievance from the last eighteen months.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">This industry is far smaller than it looks. References, referrals and reputation travel, especially within niches. The satisfaction lasts a day; the reputation lasts years.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I'm giving notice — my last day will be [date, 30 days out]. It's been good working together and I'd rather leave things properly. I'll have every SOP updated, all access transferred and a handover doc done by [date]. Happy to spend an hour with whoever takes over.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">No blame, a real notice period, and a clean handover. This client may well refer you later, and people who leave well get recommended. People who ghost get mentioned in Facebook groups.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The stay-or-go audit</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Score it honestly. Doing this on paper stops you making the decision purely on whichever day you happen to be having.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>CLIENT: [name] | With them since: [date] | Rate: $[n]/mo | [n]% of my income\n\nSCORE EACH 1–5 (5 = great)\nPays on time, every time              ___\nRate is at or above market for this   ___\nScope is respected                    ___\nRespects my stated hours              ___\nCommunicates clearly                  ___\nTreats me like a professional         ___\nI'm learning something here           ___\nGood for my portfolio / reputation    ___\nI don't dread their messages          ___\nWould refer another VA to them        ___\n                            TOTAL  ___/50\n\n40–50 → Keep. Protect this one. Ask for a raise; they can probably afford it.\n30–39 → Fixable. Pick the two lowest scores and address them directly this month.\n20–29 → On notice. Set a 60-day test with specific conditions. Start looking in parallel.\nUnder 20 → Leave. Fill the gap first, then give proper notice.\n\nTHE HONEST QUESTIONS\n• If they offered me this job today, at this rate, would I take it? [Y/N]\n• Am I staying because it's good, or because leaving is frightening?\n• What would I do with these hours if they were free?\n• Have I actually tried to fix it, or just complained about it?\n  (You cannot fire a client for breaking rules you never told them about.)\n\nBEFORE I LEAVE\n[ ] Tried a rate increase\n[ ] Tried enforcing scope in writing\n[ ] Tried resetting the response-time expectation\n[ ] Replacement income lined up, or savings to cover [n] months\n[ ] Nothing outstanding I'd be leaving broken</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Resignation and handover</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">30 days' notice minimum. Leave better than you'd have to. It costs you a few hours and it buys years of goodwill.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Hi [name],\n\nI'm giving notice — my last working day will be [date, 30 days out].\n\nNo drama behind it: [one honest, non-blaming line. \"I'm consolidating onto fewer clients in a different niche\" / \"I've taken a full-time role\" / \"The scope has grown past what I can do well alongside my other commitments.\"]\n\nI don't want to leave you stuck, so here's the plan:\n\nWEEK 1–2\n• Every SOP updated and moved into your Drive\n• A handover doc covering the daily loop, the weekly loop, all recurring deadlines, and every key contact\n• A list of everything currently in flight, with status\n\nWEEK 3\n• Available to help you interview or brief a replacement, if useful\n• Loom walkthroughs of anything that's easier shown than written\n\nWEEK 4\n• Live handover to whoever takes over, or to you\n• All access transferred, all my access revoked\n• Final invoice\n\nGenuinely been good working with you, and thank you for [something specific and true]. Happy to be a reference for you, and if you ever need a hand for a week I'm around.\n\n[Your name]\n\n[Then actually do all of it. The handover is the last impression, and it's the one people remember.]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write your walk-away criteria in advance: the three specific behaviours that mean you leave, and how much runway you need to do it.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A written walk-away policy plus your current emergency fund in months and a target.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 30 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Each criterion is an observable behaviour, not a feeling</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You calculated your runway in months, honestly</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">There is a structural fix you will try first</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You drafted the handover list you would owe them</span></label></li></ul></div>"}],"quiz":[{"q":"You need ₱56,000 gross a month and can realistically bill 110 hours. What is your floor, roughly, at ₱57 to the dollar?","options":["$$5.50/hr","$$6.20/hr","$$8.90/hr","$$12.00/hr"],"answer":2,"explain":"₱56,000 divided by 57 is about $980, divided by 110 hours is about $8.90. The trap is dividing by 160 hours, which produces a floor you cannot actually live on."},{"q":"A client says your $9 is more than they budgeted. Best response?","options":["Offer $7 to keep the deal","Hold at $9 and explain your experience again","Offer a smaller scope at the same hourly rate and let them choose","Ask what their budget is and work backwards"],"answer":2,"explain":"Move scope, not price. Discounting on first contact teaches the client your numbers are opening positions, and every future conversation starts lower."},{"q":"Which situation most clearly calls for per-output pricing?","options":["The client's volume swings wildly week to week","The client repeatedly disputes how long tasks take","The project has a clear end date and deliverable","The scope is genuinely unknown at the start"],"answer":1,"explain":"Per-output removes time from the argument entirely. Volatile volume calls for a retainer with an overflow rate, and genuinely unknown scope calls for hourly with a cap."},{"q":"How much notice should you give before a rate increase takes effect?","options":["None, it applies to the next invoice","About a week","30 to 45 days","Six months"],"answer":2,"explain":"Thirty to forty-five days is the widely used norm. It gives the client budget runway, which converts a demand into an announcement, and it makes refusal feel unreasonable rather than defensive."},{"q":"A client asks you to add a six-hour certification audit, saying it should be quick. What do you do first?","options":["Do it, it maintains goodwill","Send a change request with the estimate and a choice between paying or reprioritising, before starting","Do it and add it to the invoice as a surprise line","Refuse, it is outside scope"],"answer":1,"explain":"Before, not after. A bill they did not expect damages the relationship far more than a question they can answer in one line, and the choice between money and time makes it an easy yes."},{"q":"You have sent timestamps, screenshots and links, and the client still insists your three hours is worth one. What is the realistic read?","options":["You need better documentation","You should offer a discount to keep the peace","They have decided not to pay for that work, so try output-based pricing once and otherwise leave","Escalate to their manager"],"answer":2,"explain":"Evidence only works on someone who is arguing in good faith about facts. Switching to per-output is the one structural fix worth trying, and if that is refused the disagreement was never about hours."}],"glossary":[{"term":"Floor","def":"The hourly number below which the work costs you money once tax, fees, and unbillable hours are counted."},{"term":"Effective rate","def":"Money actually received divided by every hour spent. Always lower than your quoted rate."},{"term":"Retainer","def":"A recurring fee that reserves your capacity, used or not. Needs written rules for unused and overflow hours."},{"term":"Per-output pricing","def":"Billing the deliverable rather than the hour. Ends arguments about how long something took."},{"term":"Anchoring","def":"The first number named sets the range for everything after. This is why you should say it first."},{"term":"Scope creep","def":"Work that arrives without a change in the agreement. Normal, and expensive if you never name it."},{"term":"Change request","def":"A short written note: this is new, here is the cost or time, please approve before I start."},{"term":"Grandfathering","def":"Letting an existing client keep the old rate for a defined period. A courtesy with an expiry date, not forever."},{"term":"Net 7 / Net 15","def":"Payment due 7 or 15 days after the invoice date. Unstated terms mean whenever they feel like it."},{"term":"Kill fee","def":"An agreed payment if a project is cancelled partway. Standard for project pricing, rarely asked for."},{"term":"Runway","def":"How many months you can survive with no client. Your actual negotiating power, expressed in months."},{"term":"Concentration risk","def":"How much of your income sits with one client. Above 50 percent and they set your prices, not you."},{"term":"Discovery call","def":"The conversation where you find the scope. Do not quote inside it unless you already have the six bullet points."},{"term":"Value pricing","def":"Pricing against the client's upside rather than your hours. Works when you can name the number you move."}]} as DeepCourse;

export default course;
